Off Statistics;
Dimension 4;
Indices a,b,c,d,mu0,mu1,mu2,mu3,mu4,mu5,mu6,mu7,mu8,mu9,mu10,mu11;
Vectors p0,p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11;
Local F0=g_(1,a,p0,b,p1,p2,a,p3,p4,b,p5,p6,p7);
Local R0=4*g_(1,p3,p4,p0,p2,p1,p5,p6,p7);
Local F1=d_(a,c)*d_(b,d)*g_(1,a,p0,b,p1,p2,c,p3,p4,d,p5,p6,p7);
Local R1=4*g_(1,p3,p4,p0,p2,p1,p5,p6,p7);
Local F2=g_(1,a,p0,a,p1,p2,p3,p4,p5);
Local R2=-2*g_(1,p0,p1,p2,p3,p4,p5);
Local F3=g_(1,a,p0,p1,a,p2,p3,p4,p5);
Local R3=4*p0.p1*g_(1,p2,p3,p4,p5);
Local F4=g_(1,a,p0,p1,p2,p3,a,p4,p5,p6,p7);
Local R4=2*g_(1,p3,p0,p1,p2,p4,p5,p6,p7)+2*g_(1,p2,p1,p0,p3,p4,p5,p6,p7);
Local F5=g_(1,a,p0,p1,p2,p3,p4,p5,p6,p7,p8,p9,a);
Local R5=4*g_(1,p0,p1,p2,p3,p4,p5,p6,p7,p8,p9);
Local F6=g_(1,5_,a,p0,a,p1,p2,p3,p4,p5);
Local R6=-2*g_(1,5_,p0,p1,p2,p3,p4,p5);
Local F7=g_(1,5_,a,p0,p1,p2,p3,a,p4,p5,p6,p7);
Local R7=2*g_(1,5_,p3,p0,p1,p2,p4,p5,p6,p7)+2*g_(1,5_,p2,p1,p0,p3,p4,p5,p6,p7);
Local F8=g_(1,5_,a,p0,b,p1,p2,a,p3,p4,b,p5,p6,p7);
Local R8=4*g_(1,5_,p3,p4,p0,p2,p1,p5,p6,p7);
.sort
trace4,1;
.sort
Local C0=F0-R0;
Local C1=F1-R1;
Local C2=F2-R2;
Local C3=F3-R3;
Local C4=F4-R4;
Local C5=F5-R5;
Local C6=F6-R6;
Local C7=F7-R7;
Local C8=F8-R8;
.sort
#write "CHECK_order_sensitive_12=%E",C0
#write "CHECK_external_metrics_12=%E",C1
#write "CHECK_ordinary_odd_8=%E",C2
#write "CHECK_ordinary_even2_8=%E",C3
#write "CHECK_ordinary_even4_10=%E",C4
