#![allow(dead_code)]
pub use idenso::{W_, rep_symbols, shorthands};
use idenso::{
    dirac::GammaSimplifier,
    representations::Bispinor,
    shorthands::{chain::Chain, schoonschip::Schoonschip},
};
use serde_json::json;
use spenso::network::parsing::AtomStructureExt;
use std::{hint::black_box, time::Instant};
use symbolica::atom::{Atom, AtomCore, AtomView};
mod bracket;
mod dots;
mod epsilon;
#[derive(Clone, Copy, Debug)]
enum Method {
    Clone,
    ContainsEpsilon,
    RepeatedIndices,
    Brackets,
    Dots,
    CopiedDots,
    EpsilonCandidates,
    EpsilonFull,
    CopiedEpsilonFull,
    Schoonschip,
    Chainify,
    CollectChains,
    CollectGammaChains,
    GammaTerminal,
}
const METHODS: [Method; 14] = [
    Method::Clone,
    Method::ContainsEpsilon,
    Method::RepeatedIndices,
    Method::Brackets,
    Method::Dots,
    Method::CopiedDots,
    Method::EpsilonCandidates,
    Method::EpsilonFull,
    Method::CopiedEpsilonFull,
    Method::Schoonschip,
    Method::Chainify,
    Method::CollectChains,
    Method::CollectGammaChains,
    Method::GammaTerminal,
];
enum Outcome {
    Atom(Atom),
    Boolean(bool),
    Candidate(Atom, bool),
}
fn run(method: Method, view: AtomView<'_>) -> Outcome {
    use Method::*;
    match method {
        ContainsEpsilon => return Outcome::Boolean(epsilon::contains(view)),
        RepeatedIndices => return Outcome::Boolean(view.has_repeated_explicit_indices()),
        EpsilonCandidates => {
            let (a, b) = epsilon::candidate_walk(view);
            return Outcome::Candidate(a, b);
        }
        _ => {}
    }
    Outcome::Atom(match method {
        Clone => view.to_owned(),
        Brackets => bracket::BracketNormalizer::normalize(view),
        Dots => view.normalize_dots(),
        CopiedDots => dots::DotNormalizer::run(view),
        EpsilonFull => idenso::epsilon::EpsilonSimplifier::simplify_epsilon(&view),
        CopiedEpsilonFull => epsilon::EpsilonSimplifier::simplify_epsilon(&view),
        Schoonschip => view.schoonschip(),
        Chainify => view.chainify(Bispinor {}.into()),
        CollectChains => view.collect_chains(Bispinor {}.into()),
        CollectGammaChains => view.collect_gamma_chains(),
        GammaTerminal => view.simplify_gamma(),
        _ => unreachable!(),
    })
}
fn batch(method: Method, input: &Atom, repetitions: usize) -> f64 {
    let start = Instant::now();
    for _ in 0..repetitions {
        drop(black_box(run(method, black_box(input.as_view()))));
    }
    start.elapsed().as_nanos() as f64 / repetitions as f64
}
fn main() {
    idenso::representations::initialize();
    let _ = *epsilon::EPSILON_SYMBOL;
    let requested_rounds = std::env::args().nth(1).map_or(7, |s| s.parse().unwrap());
    let mut cases = Vec::new();
    for length in [6, 8, 10, 12] {
        let path =
            format!("/tmp/dot-normalization-improvements/before-output/axial_{length}.input");
        let input = Atom::parse(
            &std::fs::read_to_string(&path).unwrap(),
            "spenso",
            symbolica::parser::ParseSettings::symbolica(),
        )
        .unwrap();
        let mut nodes = 0usize;
        input.as_view().visitor(&mut |_| {
            nodes += 1;
            true
        });
        for method in METHODS {
            match run(method, input.as_view()) {
                Outcome::Atom(ref a) => {
                    assert_eq!(a, &input, "{method:?}/{length} changed terminal output")
                }
                Outcome::Boolean(value) => {
                    assert_eq!(value, matches!(method, Method::ContainsEpsilon))
                }
                Outcome::Candidate(ref a, changed) => {
                    assert_eq!(a, &input);
                    assert!(!changed);
                }
            }
        }
        cases.push((length, input, nodes));
    }
    let mut repetitions = vec![vec![1; METHODS.len()]; cases.len()];
    for (case, (_, input, _)) in cases.iter().enumerate() {
        for (m, method) in METHODS.iter().enumerate() {
            let estimate = batch(*method, input, 1).max(1.0);
            repetitions[case][m] = ((10_000_000.0 / estimate) as usize).clamp(1, 100_000);
        }
    }
    for round in 0..requested_rounds {
        for offset in 0..cases.len() {
            let case = (round + offset) % cases.len();
            let (length, input, nodes) = &cases[case];
            for moffset in 0..METHODS.len() {
                let m = (round + moffset) % METHODS.len();
                let method = METHODS[m];
                let reps = repetitions[case][m];
                let ns = batch(method, input, reps);
                println!(
                    "{}",
                    json!({"case":format!("axial_{length}"),"method":format!("{method:?}"),"round":round,"repetitions":reps,"ns_per_call":ns,"top_terms":input.nterms(),"nodes":nodes,"unchanged":true})
                );
            }
        }
    }
}

