sources.bracket.rs:
use spenso::{
    bracket,
    network::{
        parsing::{AtomStructureExt, StructureInferenceMode},
        tags::SPENSO_TAG,
    },
    structure::{
        OrderedStructure,
        abstract_index::AbstractIndex,
        representation::{LibraryRep, Representation},
        slot::Slot,
    },
};
use symbolica::atom::{Atom, AtomCore, AtomView};

/// Expose a bracket's factors to ordinary product identities without erasing
/// the scope of an unresolved indexed product (in particular under a power).
pub(crate) struct BracketNormalizer;

impl BracketNormalizer {
    pub(crate) fn normalize(expression: AtomView<'_>) -> Atom {
        expression.replace_map_bottom_up(|node, _context, out| {
            if let AtomView::Mul(factors) = node {
                if factors
                    .iter()
                    .any(|factor| Self::open_payload(factor).is_some())
                {
                    let product = factors.iter().fold(Atom::one(), |product, factor| {
                        product * Self::open_payload(factor).unwrap_or(factor)
                    });
                    **out = Self::scoped_product(product);
                }
                return;
            }
            let AtomView::Fun(function) = node else {
                return;
            };
            if function.get_symbol() != SPENSO_TAG.bracket || function.get_nargs() == 0 {
                return;
            }
            if function.iter().any(|factor| factor.is_zero()) {
                **out = Atom::Zero;
                return;
            }
            // Unnamed ports still depend on operand order. Only explicitly
            // wired operands have an equivalent commutative Einstein product.
            if function.iter().any(Self::has_implicit_ports) {
                return;
            }
            let product = function.iter().fold(Atom::one(), |product, factor| {
                product * Self::open_payload(factor).unwrap_or(factor)
            });
            **out = Self::scoped_product(product);
        })
    }

    fn open_payload(expression: AtomView<'_>) -> Option<AtomView<'_>> {
        let AtomView::Fun(function) = expression else {
            return None;
        };
        if function.get_symbol() != SPENSO_TAG.bracket || function.get_nargs() != 1 {
            return None;
        }
        let payload = function.iter().next()?;
        if Self::has_implicit_ports(payload) {
            return None;
        }
        // Fast inference returns EmptyStructure for a scalar. Its contracted
        // indices belong to a closed scope and must not join the outer product.
        payload
            .infer_structure::<OrderedStructure>(StructureInferenceMode::Fast)
            .ok()?;
        Some(payload)
    }

    fn scoped_product(product: Atom) -> Atom {
        // A single tensor function is already atomic. Scalar coefficients can
        // leave the bracket, but two unresolved indexed factors must stay in
        // one scope: (sum_i A_i B_i)^n is not sum_i A_i^n B_i^n.
        let mut coefficient = Atom::one();
        let mut tensors = Vec::new();
        let mut classify = |factor: AtomView<'_>| {
            if Self::contains_indices(factor) {
                tensors.push(factor.to_owned());
            } else {
                coefficient *= factor;
            }
        };
        if let AtomView::Mul(factors) = product.as_view() {
            for factor in factors {
                classify(factor);
            }
        } else {
            classify(product.as_view());
        }
        let payload = tensors
            .iter()
            .fold(Atom::one(), |product, factor| product * factor);
        if tensors.len() > 1 || matches!(payload.as_view(), AtomView::Add(_) | AtomView::Pow(_)) {
            coefficient * bracket!(payload)
        } else {
            coefficient * payload
        }
    }

    fn has_implicit_ports(expression: AtomView<'_>) -> bool {
        match expression {
            AtomView::Fun(function) => {
                let symbol = function.get_symbol();
                if symbol.is_scalar() {
                    return false;
                }
                if symbol == SPENSO_TAG.bracket {
                    return function.iter().any(Self::has_implicit_ports);
                }
                function
                    .iter()
                    .skip(usize::from(symbol == SPENSO_TAG.trace))
                    .any(|argument| {
                        Representation::<LibraryRep>::try_from(argument).is_ok()
                            && Slot::<LibraryRep, AbstractIndex>::try_from(argument).is_err()
                    })
            }
            AtomView::Mul(product) => product.iter().any(Self::has_implicit_ports),
            AtomView::Add(sum) => sum.iter().any(Self::has_implicit_ports),
            AtomView::Pow(power) => Self::has_implicit_ports(power.get_base_exp().0),
            _ => false,
        }
    }

    fn contains_indices(expression: AtomView<'_>) -> bool {
        let mut found = false;
        expression.visitor(&mut |node| {
            if let AtomView::Fun(function) = node {
                if function.get_symbol().is_scalar() {
                    return false;
                }
                found |= function.get_symbol().has_attributes_of(SPENSO_TAG.rep_)
                    && function.get_nargs() == 2;
            }
            !found
        });
        found
    }
}

sources.dots.rs:
use std::sync::LazyLock;

use spenso::{
    dot, dualizable_, g,
    network::{library::symbolic::ETS, tags::SPENSO_TAG as T},
    rank1_, self_dual_,
    structure::slot::{SlotMatch, SlotMatcher},
};
use symbolica::{
    atom::{Atom, AtomCore, AtomView, FunctionBuilder, representation::FunView},
    function,
    id::Replacement,
};

use crate::{W_, rep_symbols::RS, shorthands::metric::not_slot};

static METRIC_DOT_PRODUCT: LazyLock<[Replacement; 2]> = LazyLock::new(|| {
    let self_dual_stripped1 = self_dual_!(0; W_.d_);
    let self_dual_stripped2 = self_dual_!(0; W_.e_);
    let dualizable_stripped1 = dualizable_!(0; W_.d_);
    let dualizable_stripped2 = dualizable_!(0; W_.e_);

    [
        Replacement::new(
            g!(
                rank1_!(0; W_.d___, &self_dual_stripped1),
                function!(RS.f_, RS.a___, &self_dual_stripped2)
            )
            .to_pattern(),
            dot!(
                rank1_!(0; W_.d___, self_dual_stripped1),
                function!(RS.f_, RS.a___, self_dual_stripped2)
            ),
        )
        .when(not_slot(RS.a___)),
        Replacement::new(
            g!(
                rank1_!(0; W_.d___, &dualizable_stripped1),
                function!(RS.f_, RS.a___, &dualizable_stripped2)
            )
            .to_pattern(),
            dot!(
                rank1_!(0; W_.d___, dualizable_stripped1),
                function!(RS.f_, RS.a___, dualizable_stripped2)
            ),
        )
        .when(not_slot(RS.a___)),
    ]
});

enum DotRewrite {
    Rewritten(Atom),
    Opaque,
    Descend,
}

pub(crate) struct DotNormalizer;

impl DotNormalizer {
    pub(super) fn run(view: AtomView<'_>) -> Atom {
        let mut slots = SlotMatcher::default();
        match Self::normalize_node(view, &mut slots) {
            DotRewrite::Rewritten(result) => return result,
            DotRewrite::Opaque => return view.to_owned(),
            DotRewrite::Descend => {}
        }
        // replace_map treats even an unchanged pruning assignment as a change,
        // rebuilding its ancestors. A visitor can skip opaque payloads without
        // that work when no nested-vector or power identity applies.
        if !Self::has_rewrite(view, &mut slots) {
            return view.to_owned();
        }
        view.replace_map(
            |atom, _, out| match Self::normalize_node(atom, &mut slots) {
                DotRewrite::Rewritten(result) => **out = result,
                DotRewrite::Opaque => out.set_from_view(&atom),
                DotRewrite::Descend => {}
            },
        )
    }

    fn has_rewrite(view: AtomView<'_>, slots: &mut SlotMatcher) -> bool {
        let mut found = false;
        view.visitor(&mut |atom| {
            if found {
                return false;
            }
            match Self::normalize_node(atom, slots) {
                DotRewrite::Rewritten(_) => found = true,
                DotRewrite::Opaque => return false,
                DotRewrite::Descend => {}
            }
            !found
        });
        found
    }

    fn normalize_node(atom: AtomView<'_>, slots: &mut SlotMatcher) -> DotRewrite {
        // Metric construction owns traces and compact-vector substitution.
        // Only nested vectors and powers need this expression walk. Canonical
        // vectors have one final argument carrying their tensor structure;
        // preceding scalar parameters and slot payloads remain opaque.
        match atom {
            AtomView::Pow(power) => {
                let (base, exponent) = power.get_base_exp();
                Self::normalize_power(base, exponent, slots)
                    .map_or(DotRewrite::Descend, DotRewrite::Rewritten)
            }
            AtomView::Fun(function) if function.get_symbol().has_tag(&T.rank1) => {
                Self::normalize_nested_vector(function, slots)
                    .map_or(DotRewrite::Opaque, DotRewrite::Rewritten)
            }
            AtomView::Fun(function)
                if function.get_symbol().is_scalar()
                    || !matches!(slots.classify(atom), SlotMatch::Other) =>
            {
                DotRewrite::Opaque
            }
            _ => DotRewrite::Descend,
        }
    }

    fn normalize_nested_vector(function: FunView<'_>, slots: &mut SlotMatcher) -> Option<Atom> {
        let inner = slots.vector_argument(function)?;
        let AtomView::Fun(inner_function) = inner else {
            return None;
        };
        let compact = slots.vector_argument(inner_function)?;
        let representation = slots.compact_representation(compact)?;
        if !representation.is_base() {
            return None;
        }
        // The compact final argument identifies even an untagged inner vector;
        // the outer function must have the rank-one tag checked by the caller.
        let outer = Self::replace_last_argument(function, compact.to_owned());
        Some(g!(outer, inner))
    }

    fn normalize_power(
        base: AtomView<'_>,
        exponent: AtomView<'_>,
        slots: &mut SlotMatcher,
    ) -> Option<Atom> {
        let exponent = i64::try_from(exponent).ok()?;
        // Retain the existing integral-power convention: negative even powers
        // normalize, while negative odd and nonintegral powers remain opaque.
        if exponent % 2 == -1 {
            return None;
        }
        let AtomView::Fun(function) = base else {
            return None;
        };
        let square = if function.get_symbol() == ETS.metric {
            let mut arguments = function.iter();
            if arguments.len() != 2 {
                return None;
            }
            let SlotMatch::Explicit(first) = slots.classify(arguments.next().unwrap()) else {
                return None;
            };
            let SlotMatch::Explicit(second) = slots.classify(arguments.next().unwrap()) else {
                return None;
            };
            if first.is_concrete_index()
                || second.is_concrete_index()
                || !first.representation().is_self_dual()
                || !first.representation().matches(second.representation())
                || first.index() == second.index()
            {
                return None;
            }
            first.dimension().to_owned()
        } else if function.get_symbol().has_tag(&T.rank1) {
            let argument = slots.vector_argument(function)?;
            let SlotMatch::Explicit(slot) = slots.classify(argument) else {
                return None;
            };
            if slot.is_concrete_index() || !slot.representation().is_self_dual() {
                return None;
            }
            let compact = Self::replace_last_argument(function, slot.representation().compact());
            g!(&compact, &compact)
        } else {
            return None;
        };
        let paired = square.pow(exponent / 2);
        Some(if exponent % 2 == 1 {
            base * paired.as_view()
        } else {
            paired
        })
    }

    fn replace_last_argument(function: FunView<'_>, replacement: Atom) -> Atom {
        FunctionBuilder::new(function.get_symbol())
            .add_args(function.iter().take(function.get_nargs() - 1))
            .add_arg(replacement)
            .finish()
    }

    pub(crate) fn metric_shorthand_to_dot(view: AtomView<'_>) -> Atom {
        view.to_owned().replace_multiple(&*METRIC_DOT_PRODUCT)
    }
}


pub(crate) fn candidates(view: AtomView<'_>) -> bool { DotNormalizer::has_rewrite(view, &mut SlotMatcher::default()) }

sources.epsilon.rs:
use spenso::{
    g,
    network::parsing::{AtomStructureExt, StrictTensorFilter},
    structure::{
        abstract_index::AbstractIndex,
        dimension::Dimension,
        representation::{LibraryRep, RepName, Representation},
        slot::Slot,
    },
    tensor_symbol,
};
use symbolica::{
    atom::{Atom, AtomCore, AtomOrView, AtomView, FunctionBuilder, Symbol},
    coefficient::CoefficientView,
};

use crate::shorthands::schoonschip::Schoonschip;

spenso::symbolica_init_lazy_static! {
    /// Symbolica-level Levi-Civita symbol. The `Antisymmetric` attribute lets
    /// Symbolica canonicalize argument order and annihilate repeated arguments.
    pub static EPSILON_SYMBOL, EPSILON_SYMBOL_INNER: Symbol =
        || tensor_symbol!("spenso::epsilon"; Antisymmetric);
}

/// Builds an antisymmetric epsilon tensor with arbitrary rank.
pub fn epsilon<'a, F>(factors: impl IntoIterator<Item = F>) -> Atom
where
    F: Into<AtomOrView<'a>>,
{
    factors
        .into_iter()
        .fold(FunctionBuilder::new(*EPSILON_SYMBOL), |builder, factor| {
            builder.add_arg(factor)
        })
        .finish()
}

/// Builds an antisymmetric epsilon tensor with arbitrary rank.
///
/// Arguments are converted through `spenso::shadowing::IntoAtom`, so tests
/// and rewrite code can pass slots, atoms, atom views, symbols, and integers
/// without spelling out the conversion.
#[macro_export]
macro_rules! epsilon {
    (; $factors:expr $(,)?) => {
        $crate::epsilon::epsilon(($factors).into_iter())
    };
    ($($arg:expr),* $(,)?) => {{
        let builder = symbolica::atom::FunctionBuilder::new(*$crate::epsilon::EPSILON_SYMBOL);
        $(
            let builder = builder.add_arg(spenso::shadowing::IntoAtom::into_atom($arg));
        )*
        builder.finish()
    }};
}

/// Builds a four-dimensional Levi-Civita tensor.
pub fn epsilon4<'a, 'b, 'c, 'd>(
    mu: impl Into<AtomOrView<'a>>,
    nu: impl Into<AtomOrView<'b>>,
    rho: impl Into<AtomOrView<'c>>,
    sigma: impl Into<AtomOrView<'d>>,
) -> Atom {
    FunctionBuilder::new(*EPSILON_SYMBOL)
        .add_arg(mu)
        .add_arg(nu)
        .add_arg(rho)
        .add_arg(sigma)
        .finish()
}

/// Simplifies epsilon-metric contractions and epsilon-pair contractions.
pub trait EpsilonSimplifier {
    fn simplify_epsilon(&self) -> Atom;
}

impl EpsilonSimplifier for Atom {
    fn simplify_epsilon(&self) -> Atom {
        self.as_view().simplify_epsilon()
    }
}

impl EpsilonSimplifier for AtomView<'_> {
    fn simplify_epsilon(&self) -> Atom {
        EpsilonSimplifierPass::run(*self)
    }
}

struct EpsilonSimplifierPass;

impl EpsilonSimplifierPass {
    /// Runs the epsilon identities to a fixed point, then lets metric
    /// simplification consume any determinants that collapsed to traces.
    fn run(expr: AtomView<'_>) -> Atom {
        // Force Symbolica to register epsilon as antisymmetric before any
        // builders below create new epsilon nodes.
        let _ = *EPSILON_SYMBOL;
        if !Self::contains_epsilon(expr) {
            return expr.to_owned();
        }

        let mut current = expr.schoonschip();

        loop {
            let mut changed = false;
            let next = current.replace_map(|term, _context, out| {
                let rewritten = match term {
                    AtomView::Pow(_) => Self::simplify_power(term),
                    AtomView::Mul(_) => Self::simplify_pair_product(term),
                    _ => None,
                };
                if let Some(rewritten) = rewritten {
                    changed = true;
                    **out = rewritten;
                }
            });
            if !changed {
                return next;
            }

            // Epsilon identities introduce determinants whose metrics may now
            // contract. Unchanged visits need no further tensor normalization.
            let next = next.schoonschip();
            if next == current {
                return next;
            }

            current = next;
        }
    }

    fn contains_epsilon(expr: AtomView<'_>) -> bool {
        match expr {
            AtomView::Fun(f) => {
                f.get_symbol() == *EPSILON_SYMBOL || f.iter().any(Self::contains_epsilon)
            }
            AtomView::Add(add) => add.iter().any(Self::contains_epsilon),
            AtomView::Mul(mul) => mul.iter().any(Self::contains_epsilon),
            AtomView::Pow(pow) => pow.iter().any(Self::contains_epsilon),
            AtomView::Num(_) | AtomView::Var(_) => false,
        }
    }

    /// Applies the repeated-epsilon identity to powers:
    /// `epsilon(a_1,...,a_n)^k -> det(g(a_i,a_j)) epsilon(a_1,...,a_n)^(k-2)`.
    ///
    /// This handles the common canonical form where Symbolica has already
    /// merged an epsilon product into a positive integer power.
    fn simplify_power(expr: AtomView<'_>) -> Option<Atom> {
        let AtomView::Pow(pow) = expr else {
            return None;
        };
        let (base, exponent) = pow.get_base_exp();
        let exponent = Self::positive_integer(exponent)?;
        if exponent < 2 {
            return None;
        }
        let (epsilon_args, representation) = Self::epsilon_args(base)?;
        if !representation.rep.is_self_dual() {
            return None;
        }

        Some(
            Self::metric_determinant(&epsilon_args, &epsilon_args)
                * Self::power(base, exponent - 2),
        )
    }

    /// Applies the epsilon-pair contraction:
    /// `epsilon(a_1,...,a_n) epsilon(b_1,...,b_n) -> det(g(a_i,b_j))`.
    ///
    /// Extra multiplicative factors are preserved around the determinant.
    fn simplify_pair_product(expr: AtomView<'_>) -> Option<Atom> {
        let AtomView::Mul(product) = expr else {
            return None;
        };
        let mut epsilons = product
            .iter()
            .enumerate()
            .filter(|(_, factor)| {
                matches!(factor, AtomView::Fun(fun) if fun.get_symbol() == *EPSILON_SYMBOL)
            })
            .peekable();

        while let Some((left_index, left)) = epsilons.next() {
            // A lone epsilon needs no representation parsing or owned arguments.
            epsilons.peek()?;
            let Some((left_args, left_rep)) = Self::epsilon_args(left) else {
                continue;
            };

            for (right_index, right) in epsilons.clone() {
                let Some((right_args, right_rep)) = Self::epsilon_args(right) else {
                    continue;
                };
                // A determinant pairs a representation with its dual. In
                // particular, two SU(3) triplet epsilons cannot contract.
                if left_args.len() != right_args.len() || left_rep.dual() != right_rep {
                    continue;
                }

                let determinant = Self::metric_determinant(&left_args, &right_args);
                let spectators =
                    Atom::mul_many(product.iter().enumerate().filter_map(|(index, factor)| {
                        (index != left_index && index != right_index).then_some(factor)
                    }));
                return Some(spectators * determinant);
            }
        }

        None
    }

    fn positive_integer(expr: AtomView<'_>) -> Option<i64> {
        let AtomView::Num(number) = expr else {
            return None;
        };
        let CoefficientView::Natural(value, 1, 0, 1) = number.get_coeff_view() else {
            return None;
        };

        (value > 0).then_some(value)
    }

    fn power(base: AtomView<'_>, exponent: i64) -> Atom {
        match exponent {
            0 => Atom::num(1),
            1 => base.to_owned(),
            _ => base.to_owned().pow(Atom::num(exponent)),
        }
    }

    /// Emits the determinant `det(g(left_i,right_j))` by summing over all
    /// signed permutations of the right indices.
    fn metric_determinant(left: &[Atom], right: &[Atom]) -> Atom {
        let mut permutation = (0..right.len()).collect::<Vec<_>>();
        let mut sum = Atom::Zero;
        Self::determinant_terms(left, right, 0, &mut permutation, 1, &mut sum);
        sum
    }

    fn determinant_terms(
        left: &[Atom],
        right: &[Atom],
        position: usize,
        permutation: &mut [usize],
        sign: i64,
        sum: &mut Atom,
    ) {
        if position == permutation.len() {
            let term = left
                .iter()
                .enumerate()
                .fold(Atom::num(sign), |product, (i, arg)| {
                    product * g!(arg.clone(), right[permutation[i]].clone())
                });
            *sum += term;
            return;
        }

        for i in position..permutation.len() {
            permutation.swap(position, i);
            let next_sign = if i == position { sign } else { -sign };
            Self::determinant_terms(left, right, position + 1, permutation, next_sign, sum);
            permutation.swap(position, i);
        }
    }

    fn epsilon_args(epsilon: AtomView<'_>) -> Option<(Vec<Atom>, Representation<LibraryRep>)> {
        let AtomView::Fun(f) = epsilon else {
            return None;
        };
        if f.get_symbol() != *EPSILON_SYMBOL {
            return None;
        }

        let mut representation = None;
        let mut args = Vec::with_capacity(f.get_nargs());
        for arg in f.iter() {
            let rep = Representation::<LibraryRep>::try_from(arg)
                .ok()
                .or_else(|| {
                    // Compact vectors can have ordinary Symbolica heads and
                    // scalar labels, but expose exactly one bare representation.
                    let AtomView::Fun(vector) = arg else {
                        return None;
                    };
                    if vector.get_symbol().is_scalar() {
                        return None;
                    }
                    let mut reps = vector.iter().filter_map(|argument| {
                        Representation::<LibraryRep>::try_from(argument)
                            .ok()
                            .map(|rep| (argument, rep))
                    });
                    let (rep_arg, rep) = reps.next()?;
                    if reps.next().is_some()
                        || Slot::<LibraryRep, AbstractIndex>::try_from(rep_arg).is_ok()
                        || vector.iter().any(|argument| {
                            argument != rep_arg
                                && (argument.is_tensorial(StrictTensorFilter::Tagged)
                                    || argument.is_tensorial(StrictTensorFilter::ContainsReps))
                        })
                    {
                        return None;
                    }
                    Some(rep)
                })?;
            if representation.is_some_and(|previous| previous != rep) {
                return None;
            }
            representation = Some(rep);
            args.push(arg.to_owned());
        }
        let representation = representation?;
        if !representation.rep.is_self_dual()
            && representation.dim != Dimension::Concrete(args.len())
        {
            return None;
        }
        Some((args, representation))
    }
}


pub(crate) fn contains(view: AtomView<'_>) -> bool {
    EpsilonSimplifierPass::contains_epsilon(view)
}
pub(crate) fn candidate_walk(view: AtomView<'_>) -> (Atom, bool) {
    let mut changed = false;
    let next = view.replace_map(|term, _, out| {
        let rewritten = match term {
            AtomView::Pow(_) => EpsilonSimplifierPass::simplify_power(term),
            AtomView::Mul(_) => EpsilonSimplifierPass::simplify_pair_product(term),
            _ => None,
        };
        if let Some(rewritten) = rewritten {
            changed = true;
            **out = rewritten;
        }
    });
    (next, changed)
}

