#![allow(dead_code)]
use idenso::shorthands::schoonschip::Schoonschip;
pub use idenso::{W_, rep_symbols, shorthands};
use serde_json::json;
use spenso::network::tags::SPENSO_TAG;
use std::{hint::black_box, path::Path, time::Instant};
use symbolica::{
    atom::{Atom, AtomCore, AtomView},
    function, symbol,
};
mod dots;
mod unguarded;
#[derive(Clone, Copy, Debug)]
enum Method {
    Production,
    Copied,
    Guarded,
    GuardScan,
}
const METHODS: [Method; 4] = [
    Method::Production,
    Method::Copied,
    Method::Guarded,
    Method::GuardScan,
];
fn run(method: Method, input: AtomView<'_>) {
    match method {
        Method::Production => drop(black_box(input.normalize_dots())),
        Method::Copied => drop(black_box(unguarded::DotNormalizer::run(input))),
        Method::Guarded => drop(black_box(dots::DotNormalizer::run(input))),
        Method::GuardScan => {
            black_box(dots::guard_scan(input));
        }
    }
}
fn batch(method: Method, input: &Atom, reps: usize) -> f64 {
    let start = Instant::now();
    for _ in 0..reps {
        run(method, black_box(input.as_view()));
    }
    start.elapsed().as_nanos() as f64 / reps as f64
}
fn main() {
    idenso::representations::initialize();
    let _ = *idenso::epsilon::EPSILON_SYMBOL;
    for head in [
        "cleanup_benchmark::V",
        "cleanup_benchmark::W",
        "metric_contraction_benchmark::p",
        "metric_contraction_benchmark::q",
    ] {
        SPENSO_TAG.rank_one_tensor_symbol(head);
    }
    for i in 0..10 {
        SPENSO_TAG.rank_one_tensor_symbol(&format!("metric_benchmark::p{i}"));
    }
    let source = Path::new("/tmp/dot-normalization-improvements/before-output");
    let mut paths = std::fs::read_dir(source)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "input"))
        .collect::<Vec<_>>();
    paths.sort();
    let mut cases = paths
        .into_iter()
        .map(|p| {
            let text = std::fs::read_to_string(&p).unwrap();
            let atom = Atom::parse(
                &text,
                "spenso",
                symbolica::parser::ParseSettings::symbolica(),
            )
            .unwrap();
            (p.file_stem().unwrap().to_str().unwrap().to_owned(), atom)
        })
        .collect::<Vec<_>>();
    let scalar = symbol!("guard_benchmark::opaque");
    for n in [64, 1024] {
        cases.push((
            format!("scalar_heavy_{n}"),
            Atom::add_many((0..n).map(|i| function!(scalar, i)).collect::<Vec<_>>()).pow(7),
        ));
    }
    let mut changed = Vec::new();
    for (name, input) in &cases {
        let production = input.normalize_dots();
        let copied = unguarded::DotNormalizer::run(input.as_view());
        let guarded = dots::DotNormalizer::run(input.as_view());
        assert_eq!(production, copied, "copied/{name}");
        assert_eq!(copied, guarded, "guarded/{name}");
        let candidate = dots::guard_scan(input.as_view());
        assert_eq!(candidate, production != *input, "candidate/{name}");
        changed.push(candidate);
    }
    let mut reps = vec![[1; 4]; cases.len()];
    for (i, (_, input)) in cases.iter().enumerate() {
        for (j, method) in METHODS.iter().enumerate() {
            reps[i][j] =
                ((5_000_000.0 / batch(*method, input, 1).max(1.0)) as usize).clamp(1, 100_000)
        }
    }
    for round in 0..5 {
        for offset in 0..cases.len() {
            let i = (round + offset) % cases.len();
            let (name, input) = &cases[i];
            for moffset in 0..4 {
                let m = (round + moffset) % 4;
                let method = METHODS[m];
                println!(
                    "{}",
                    json!({"case":name,"method":format!("{method:?}"),"round":round,"repetitions":reps[i][m],"ns_per_call":batch(method,input,reps[i][m]),"productive":changed[i],"exact_parity":true})
                );
            }
        }
    }
}

