from pathlib import Path
import json,statistics,collections,hashlib
out=Path('/tmp/dot-normalization-improvements/visitor-guard');root=out.parent
rows=[json.loads(line) for line in (out/'raw.jsonl').read_text().splitlines()]
groups=collections.defaultdict(list)
for row in rows:groups[row['case'],row['method']].append(row['ns_per_call'])
assert all(len(v)==5 for v in groups.values())
records=[]
for (case,method),values in sorted(groups.items()):
 records.append({'case':case,'method':method,'median_ms':statistics.median(values)/1e6,'samples_ms':[x/1e6 for x in values]})
lookup={(r['case'],r['method']):r['median_ms'] for r in records}
productive={r['case']:r['productive'] for r in rows}
comparison=[{'case':case,'productive':productive[case],'copied_ms':lookup[case,'Copied'],'guarded_ms':lookup[case,'Guarded'],'guard_scan_ms':lookup[case,'GuardScan'],'speedup':lookup[case,'Copied']/lookup[case,'Guarded']} for case in sorted(productive)]
summary={'methodology':{'cpu':7,'rounds':5,'cases':len(productive),'samples':len(rows),'target_batch_ms':5,'destruction_included':True,'validation':'Every copied and guarded result equals linked production. Candidate truth equals whether production changes each parsed input. All assertions passed.','guard':'Final production implementation uses one shared normalize_node dispatcher. A productive root returns its rewrite immediately; an opaque root returns its owned view. Otherwise a visitor with identical opaque scopes detects actual rewrites, then the rewriting traversal runs only when needed. Successful below-root candidate computation is repeated in that traversal.','comparison':'Primary guard speedup compares copied vs guarded implementations in the same executable. Production timing is included for caller/code-placement context.'},'comparison':comparison,'records':records}
(out/'summary.json').write_text(json.dumps(summary,indent=2))
manifest={'files':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in out.iterdir() if p.is_file() and p.name!='manifest.json'},'inputs':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in (root/'before-output').glob('*.input')},'linked_libraries':{name:{'path':path,'sha256':hashlib.sha256(Path(path).read_bytes()).hexdigest()} for name,path in [arg.split('=',1) for arg in json.loads((out/'build-command.json').read_text()) if arg.endswith('.rlib') and '=' in arg]}}
(out/'manifest.json').write_text(json.dumps(manifest,indent=2))
summary['raw_rows']=rows
summary['sources']={name:(out/name).read_text() for name in ['driver.rs','dots.rs','unguarded.rs','build-command.json','source-sha256.json','manifest.json','summarize.py']}
(root/'visitor-guard.json').write_text(json.dumps(summary,indent=2))
for row in comparison:
 if row['case'].startswith('axial_') or row['productive'] or row['case'] in ['scalar_heavy_64','scalar_heavy_1024','many_spectators_hit','many_spectators_miss','no_metric']:
  print(row)
print('cases',len(productive),'rows',len(rows),'productive',sum(productive.values()))
